//! The album art gate's Rust half (2b PR-(4), AP-4): the bake's `ART1` blob re-read
//! through the **shipping** parser, and the paint plan checked against the scene
//! vocabulary. `make album-art-check` runs this beside the tool's self-test and the
//! two-bake determinism leg.
//!
//! The blob is `assets/art1.bin`, generated by `scripts/album_art.py` from the tracked
//! cover. A fresh clone has no asset and no generated module, so this test only runs after
//! `make album-bake` — the gate depends on it, and `HAS_ART = false` is a legal album.
use album_player::assets;
use gba_art::art1;
use gba_scene::{Rect, Source, Writes};

#[test]
fn the_album_blob_re_reads_through_the_shipping_parser() {
    if !assets::HAS_ART {
        assert!(assets::ART1.is_empty());
        assert_eq!(assets::ART_TILES, 0);
        assert_eq!(
            assets::POOL_IMAGE,
            256,
            "no selection means the variant's ceiling"
        );
        return;
    }
    let art = art1::parse(assets::ART1).expect("the bake's ART1 is refused by its own reader");
    assert_eq!(art.width_px, assets::ART_BOX_PX_W);
    assert_eq!(art.height_px, assets::ART_BOX_PX_H);
    assert_eq!(art.n_tiles(), assets::ART_TILES);
    assert_eq!(art.n_palette_banks, assets::ART_PALETTE_BANKS);
    assert_eq!(assets::ART1.len(), assets::ART1_BYTES);
    assert!(
        assets::ART_TILES <= album_player::layout::IMAGE_TILES_MAX,
        "the selected box must stay inside the variant's declared image ceiling"
    );
    assert_eq!(
        assets::POOL_IMAGE,
        assets::ART_TILES,
        "Decision B: the audited image term is the selected box"
    );
}

#[test]
fn painting_the_art_writes_only_art_cells_inside_the_rectangle() {
    if !assets::HAS_ART {
        return;
    }
    let art = art1::parse(assets::ART1).expect("parsed in the leg above");
    let rect = Rect::new(0, 0, 30, 16);
    let mut writes = Writes::new();
    let pushed = gba_art::paint(&art, rect, 3, &mut writes);
    assert_eq!(pushed as u32, assets::ART_TILES);
    assert_eq!(writes.len(), pushed);
    assert_eq!(writes.dropped(), 0);
    for w in writes.as_slice() {
        assert_eq!(w.source, Source::Art);
        assert!(rect.contains(u32::from(w.x), u32::from(w.y)));
        assert!(
            w.bank >= 3 && w.bank < 3 + assets::ART_PALETTE_BANKS as u8,
            "bank {} is outside the art element's declared banks 3..6",
            w.bank
        );
    }
}
